fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
    broadcast use super::imap::group_imap_lemmas;
    broadcast use group_multiset_axioms;

    // In the pre state, we're in Responding mode with idx == num_clients
    // For any valid index i (i < num_clients), we have:
    // - combiner_has(i) requires i >= pre.combiner.get_Responding_idx() == num_clients
    // - But valid_idx(i) requires i < num_clients
    // - So combiner_has(i) is false for all valid i
    // 
    // In the post state, combiner is Collecting with empty elements, so combiner_has(i) is also false.
    //
    // Since all invariants either don't depend on combiner or combiner_has is false in both states,
    // the invariants that held in the pre state also hold in the post state.
    //
    // The state transition doesn't change clients, slots, requests, or responses,
    // so all field-based invariants are preserved.
    assert forall |i: nat| pre.valid_idx(i) implies !pre.combiner_has(i) by {
        let idx = pre.combiner.get_Responding_idx();
        assert(idx == pre.num_clients);
        assert(pre.valid_idx(i) implies i < pre.num_clients);
        assert(i < pre.num_clients implies !(i >= idx));
    }
    assert forall |i: nat| post.valid_idx(i) implies !post.combiner_has(i) by {
        assert(post.combiner.is_Collecting());
        assert(post.combiner.get_Collecting_elems().len() == 0);
        assert(post.valid_idx(i) implies i < post.num_clients);
        assert(i < 0 implies false);
    }
}

